var session_source := load("res://scenes/game/game_session.tscn") as PackedScene
var small_source := load("res://scenes/game/map_small.tscn") as PackedScene
var large_source := load("res://scenes/game/map_large.tscn") as PackedScene
if session_source == null:
    _custom_print("GameSession scene was not available.")
elif small_source == null or large_source == null:
    _custom_print("Map variant scene was not available.")
else:
    var session_root := session_source.instantiate()
    var medium_map := session_root.get_node_or_null("MapMedium") as Node2D
    if medium_map != null:
        medium_map.visible = true
        var medium_boundary := medium_map.get_node_or_null("FallBoundary") as Area2D
        if medium_boundary != null:
            medium_boundary.monitoring = true
    var small_map := session_root.get_node_or_null("MapSmall") as Node2D
    if small_map == null:
        small_map = small_source.instantiate() as Node2D
        small_map.name = "MapSmall"
        session_root.add_child(small_map)
        small_map.owner = session_root
    small_map.visible = false
    var small_boundary := small_map.get_node_or_null("FallBoundary") as Area2D
    if small_boundary != null:
        small_boundary.monitoring = false
        if not small_boundary.body_exited.is_connected(Callable(session_root, "_on_island_body_exited")):
            small_boundary.body_exited.connect(Callable(session_root, "_on_island_body_exited"), Object.CONNECT_PERSIST)
    var large_map := session_root.get_node_or_null("MapLarge") as Node2D
    if large_map == null:
        large_map = large_source.instantiate() as Node2D
        large_map.name = "MapLarge"
        session_root.add_child(large_map)
        large_map.owner = session_root
    large_map.visible = false
    var large_boundary := large_map.get_node_or_null("FallBoundary") as Area2D
    if large_boundary != null:
        large_boundary.monitoring = false
        if not large_boundary.body_exited.is_connected(Callable(session_root, "_on_island_body_exited")):
            large_boundary.body_exited.connect(Callable(session_root, "_on_island_body_exited"), Object.CONNECT_PERSIST)
    var packed := PackedScene.new()
    var pack_error := packed.pack(session_root)
    var save_error := ResourceSaver.save(packed, "res://scenes/game/game_session.tscn")
    session_root.free()
    _custom_print("session %s %s" % [error_string(pack_error), error_string(save_error)])
